import { uuidv4 } from '../../../core/utils/uuidv4.js';
import {
  FormFieldMessage,
  FormFieldMessageContextState,
} from '../contexts/FormFieldMessageContext.js';
import type {
  FormFieldControlMessage,
  FormFieldCustomMessage,
} from '../contexts/FormFieldMessageContext.js';

export const enum FormFieldMessagesAction {
  ADDMESSAGE = 'addmessage',
  REMOVEMESSAGE = 'removemessage',
}

export type FormFieldMessagesReducerAction =
  | {
      type: FormFieldMessagesAction.ADDMESSAGE;
      payload: Omit<FormFieldControlMessage, 'id'> | FormFieldCustomMessage;
    }
  | {
      type: FormFieldMessagesAction.REMOVEMESSAGE;
      payload: Pick<FormFieldMessage, 'id' | 'messageType'>;
    };

type HTMLFormControlElement =
  | HTMLSelectElement
  | HTMLInputElement
  | HTMLTextAreaElement;

/**
 * Typeguard function that will check if message is a formcontrol (internal) message.
 * @internal
 */
function isFormControlPayload(
  payload:
    | Omit<FormFieldControlMessage, 'id'>
    | FormFieldCustomMessage
    | FormFieldControlMessage,
  messageType?: 'formcontrol' | 'custom',
): payload is FormFieldControlMessage | Omit<FormFieldControlMessage, 'id'> {
  return messageType === 'formcontrol';
}

/** FormFieldMessage reducer function used for managing FormFieldMessages and FormFieldCustomMessages. */
export function formFieldMessagesReducer(
  state: FormFieldMessageContextState,
  action: FormFieldMessagesReducerAction,
  controlId: string,
): FormFieldMessageContextState {
  let formControlMessages = state.formControlMessages;
  let customMessages = state.customMessages;
  let hasError = state.hasError;

  // handle adding of form messages
  if (action.type === FormFieldMessagesAction.ADDMESSAGE) {
    const { payload } = action;
    const { messageType, ...remainingPayload } = payload;

    // block form submission by setting the validity state of the form control
    if (
      remainingPayload.variant === 'error' &&
      (messageType === 'custom' ||
        remainingPayload['validityStateKey'] === 'customError')
    ) {
      const formControlElement = document.querySelector(
        `#${controlId}`,
      ) as HTMLFormControlElement;

      formControlElement?.setCustomValidity(' ');
    }

    // Is a browser/strato message
    if (isFormControlPayload(remainingPayload, messageType)) {
      if (
        !formControlMessages.some((message) => {
          return message.validityStateKey === remainingPayload.validityStateKey;
        })
      ) {
        formControlMessages.push({
          id: `strato-${uuidv4()}`,
          ...remainingPayload,
        });
      }
      // Is a custom error
    } else {
      if (
        'id' in remainingPayload &&
        !formControlMessages.some((message) => {
          return message.id === remainingPayload.id;
        }) &&
        !customMessages.some((message) => {
          return message.id === remainingPayload.id;
        })
      ) {
        customMessages.push(remainingPayload);
      }
    }

    if (remainingPayload.variant === 'error') {
      hasError = true;
    }
  }

  if (action.type === FormFieldMessagesAction.REMOVEMESSAGE) {
    const { payload } = action;

    // remove the message from formcontrol or custom messages
    if (payload.messageType === 'formcontrol') {
      formControlMessages = formControlMessages.filter((message) => {
        return message.id !== payload.id;
      });
    } else {
      customMessages = customMessages.filter((message) => {
        return message.id !== payload.id;
      });
    }

    // reevaluate the hasError state
    if (hasError) {
      const hasCustomError = customMessages.some((message) => {
        return message.variant === 'error';
      });

      const hasFormControlError = formControlMessages.some((message) => {
        return message.variant === 'error';
      });

      if (!hasCustomError && !hasFormControlError) {
        const formControlElement = document.querySelector(
          `#${controlId}`,
        ) as HTMLFormControlElement;

        formControlElement?.setCustomValidity('');
      }

      hasError = hasCustomError || hasFormControlError;
    }
  }

  return { formControlMessages, customMessages, hasError, isDirty: true };
}
